// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testFuzz_property(address actor, address ref, uint256 waitTime) public {
        vm.assume(actor != address(0));
        vm.assume(ref != address(0));
        waitTime = bound(waitTime, 0, c.DRUGS_TO_PRODUCE_1KILO());
        c.seedMarket(1000);
        vm.prank(actor);
        c.getFreeKilo();
        uint256 kilosBefore = c.Kilos(actor);
        assertTrue(kilosBefore > 0);
        vm.warp(block.timestamp + waitTime);
        vm.prank(actor);
        c.collectDrugs(ref);
        assertTrue(c.Kilos(actor) >= kilosBefore);
    }
}
